#!/usr/bin/env bash
# Export every part of biped10_parts.scad to STL with OpenSCAD.
#
#   ./export_stl.sh                 -> ./stl/*.stl (for printing / laser cutting / checking)
#   ./export_stl.sh --sim           -> overwrite the simulator meshes in
#                                      biped_walker/assets/biped10/meshes
#
# The simulator meshes in the repo were generated by the NumPy mirror of these
# parts (biped_walker/cad/parts.py); OpenSCAD's export has smoother holes but
# the same dimensions. If you change a part's dimensions, update parts.py too
# and run `python -m biped_walker.cad.biped10_design` so the masses, inertias
# and joint layout used by the simulator are regenerated.
set -euo pipefail
cd "$(dirname "$0")"
OUT=stl
if [[ "${1:-}" == "--sim" ]]; then OUT=../../biped_walker/assets/biped10/meshes; fi
mkdir -p "$OUT"
for part in mg996r servo_horn bracket_multi u_bracket_24 u_bracket_30 u_bracket_42 yaw_plate foot_plate \
            chassis_frame chassis_plates battery pcb; do
  echo "exporting $part"
  openscad -q -D "part=\"$part\"" -o "$OUT/$part.stl" biped10_parts.scad
done
